// Benchmark boilerplate generated by Benchmark

import Benchmark
import Contexts
import Foundation
import HTMLKit
import SteamEagle

let benchmarks: @Sendable () -> Void = {

    struct TestR: Rendable {
        let x: String

        @Contexts.ContentBuilder
        var body: some Rendable {
            Content.tag(
                Tag.h1,
                EmptyContent.test(
                    String(repeating: x, count: 50)
                ))
        }
    }

    struct TestHTMLKit: View {
        let x: String

        @HTMLKit.ContentBuilder<HTMLKit.Content>
        var body: any HTMLKit.Content {
            Heading1 {
                String(repeating: x, count: 50)
            }
        }
    }

    let data = (0...10000).map { _ in
        String.init(repeating: Int.random(in: 0...10_000_000).description, count: 10)
    }

    let simpleRenderer = SimpleRenderer()
    let arrayRenderer = ArrayRenderer()

    Benchmark("SimpleRenderer") { benchmark in

        benchmark.startMeasurement()

        for _ in benchmark.scaledIterations {

            for x in 0...10000 {
                simpleRenderer.render(TestR(x: data[x]))
                blackHole(simpleRenderer.printing())
            }
        }

        benchmark.stopMeasurement()
    }

    Benchmark("ArrayRenderer") { benchmark in
        benchmark.startMeasurement()

        for _ in benchmark.scaledIterations {

            for x in 0...10000 {
                arrayRenderer.render(TestR(x: data[x]))
                blackHole(arrayRenderer.printing())
            }
        }

        benchmark.stopMeasurement()
    }

    let htmlkitRenderer = HTMLKit.Renderer()

    Benchmark("HtmlKitRenderer") { benchmark in
        benchmark.startMeasurement()

        for _ in benchmark.scaledIterations {
            for x in 0...10000 {
                blackHole(try htmlkitRenderer.render(view: TestHTMLKit(x: data[x])))
            }
        }

        benchmark.stopMeasurement()
    }

}
